<script>const testFaDigits='۰۱۲۳۴۵۶۷۸۹',testEnNumber=v=>String(v).replace(/[۰-۹]/g,d=>String(testFaDigits.indexOf(d))).replace(/[^0-9-]/g,''),testFaNumber=v=>String(v).replace(/\d/g,d=>testFaDigits[d]);function normalizeTestNumber(input){let value=Number(testEnNumber(input.value)||0),min=Number(input.dataset.min??0),max=Number(input.dataset.max??100);value=Math.max(min,Math.min(max,value));input.value=testFaNumber(value)}document.addEventListener('input',e=>{if(e.target.classList.contains('test-fa-number'))normalizeTestNumber(e.target)});document.addEventListener('keydown',e=>{if(!e.target.classList.contains('test-fa-number')||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.target.value=testFaNumber(Number(testEnNumber(e.target.value)||0)+(e.key==='ArrowUp'?1:-1));normalizeTestNumber(e.target)});document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('.test-fa-number').forEach(normalizeTestNumber));document.addEventListener('submit',e=>e.target.querySelectorAll?.('.test-fa-number').forEach(input=>input.value=testEnNumber(input.value)));</script>
<script>window.runUnifiedFixtureTest=async function(){const forms=[...document.querySelectorAll('#tests form')].filter(f=>!f.action.includes('delete'));const target=document.createElement('form');target.method='POST';target.action='/analytics/_test/run-all';forms.forEach(form=>new FormData(form).forEach((value,key)=>{if(key==='_token'&&target.querySelector('[name="_token"]'))return;const input=document.createElement('input');input.type='hidden';input.name=key;input.value=testEnNumber(value);target.appendChild(input);}));document.body.appendChild(target);if(await AppDialog.confirm('تمام مراحل اجرا شوند؟'))target.submit();else target.remove();};</script>
